use crate::models::{Category, Tool, ToolEngineConfig, ToolUiConfig};
use crate::registry::EngineRegistry;
use serde::Deserialize;
use std::collections::HashMap;

const RAW_TOOLS_JSON: &str = include_str!("../../../shared/data/tools.json");
const RAW_CATEGORIES_JSON: &str = include_str!("../../../shared/data/categories.json");
/// Catalog tool → engine/action mapping generated by `scripts/generate-engine-tools.py`.
const RAW_ENGINE_TOOLS_JSON: &str = include_str!("../../../shared/data/engine-tools.json");

#[derive(Deserialize, Clone)]
pub struct EngineToolMapping {
    pub id: String,
    #[serde(default)]
    pub registry_slug: Option<String>,
    /// Additional registry slugs served by the same catalog tool (aliases).
    #[serde(default)]
    pub registry_slugs: Vec<String>,
    #[serde(default)]
    pub engine: Option<String>,
    #[serde(default)]
    pub action: Option<String>,
    pub status: String,
    #[serde(default)]
    pub ui_category: Option<String>,
    #[serde(default)]
    pub note: Option<String>,
    #[serde(default)]
    pub requires: Vec<String>,
    #[serde(default)]
    pub network: bool,
}

#[derive(Deserialize)]
struct EngineToolsFile {
    tools: Vec<EngineToolMapping>,
}

fn title_case(id: &str) -> String {
    id.split('-')
        .map(|w| {
            let mut c = w.chars();
            match c.next() {
                Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
                None => String::new(),
            }
        })
        .collect::<Vec<_>>()
        .join(" ")
}

fn features_for(m: Option<&EngineToolMapping>) -> Vec<String> {
    let mut f = vec!["client-side".to_string()];
    if let Some(m) = m {
        if let (Some(e), Some(a)) = (&m.engine, &m.action) {
            f.push("wasm-accelerated".into());
            f.push(format!("engine:{e}"));
            f.push(format!("action:{a}"));
            f.push(format!("status:{}", m.status));
        }
        if m.requires.iter().any(|r| r == "files") {
            f.push("accepts-files".into());
        }
        if !m.network {
            f.push("offline".into());
        }
    }
    f
}

#[derive(Deserialize)]
struct RawTool {
    id: usize,
    name: String,
    slug: String,
    category: String,
    description: String,
    #[serde(default)]
    status: Option<String>,
}

#[derive(Deserialize)]
struct RawCategory {
    name: String,
    description: String,
}

pub struct ToolRegistry {
    tools: Vec<Tool>,
    categories: Vec<Category>,
}

impl ToolRegistry {
    /// Builds the registry from the embedded `shared/data/*.json` files.
    /// Returns a descriptive error (instead of panicking) when generated data
    /// is out of sync.
    pub fn new(engine_registry: &EngineRegistry) -> Result<Self, String> {
        let raw_tools: Vec<RawTool> = serde_json::from_str(RAW_TOOLS_JSON)
            .map_err(|e| format!("shared/data/tools.json is invalid: {e}"))?;
        let raw_categories: Vec<RawCategory> = serde_json::from_str(RAW_CATEGORIES_JSON)
            .map_err(|e| format!("shared/data/categories.json is invalid: {e}"))?;

        let mut category_counts: HashMap<String, usize> = HashMap::new();
        let engine_tools: EngineToolsFile = serde_json::from_str(RAW_ENGINE_TOOLS_JSON)
            .map_err(|e| format!("shared/data/engine-tools.json is invalid: {e}"))?;
        let mut by_slug: HashMap<String, EngineToolMapping> = HashMap::new();
        for m in &engine_tools.tools {
            if let Some(slug) = &m.registry_slug {
                by_slug.insert(slug.clone(), m.clone());
            }
            for alias in &m.registry_slugs {
                let mut aliased = m.clone();
                aliased.registry_slug = Some(alias.clone());
                by_slug.insert(alias.clone(), aliased);
            }
        }

        // Specific tool slugs that have dedicated interactive UI components.
        let dedicated_ui: HashMap<&str, (&str, &str)> = [
            ("text-case-converter", ("text-engine", "TextCaseConverter")),
            ("word-counter", ("text-engine", "WordCounter")),
            ("json-formatter", ("text-engine", "JsonFormatter")),
            ("base64-encoder-decoder", ("text-engine", "Base64EncoderDecoder")),
            ("url-encoder-decoder", ("text-engine", "UrlEncoderDecoder")),
            ("image-cropper", ("image-engine", "ImageCropperTool")),
        ]
        .into_iter()
        .collect();

        let engine_config = |eid: &str| {
            engine_registry.get(eid).map(|manifest| ToolEngineConfig {
                id: manifest.id.clone(),
                version: manifest.version.clone(),
                r#type: manifest.r#type.clone(),
                url: manifest.url.clone(),
                glue: manifest.glue.clone(),
                worker: manifest.worker.clone(),
                hash: Some(manifest.hash.clone()),
            })
        };
        let served = |m: &EngineToolMapping| m.status == "implemented" || m.status == "partial";

        let mut tools: Vec<Tool> = raw_tools
            .into_iter()
            .map(|rt| {
                *category_counts.entry(rt.category.clone()).or_insert(0) += 1;
                let mapping = by_slug.get(rt.slug.as_str());
                let dedicated = dedicated_ui.get(rt.slug.as_str());
                let engine_id: Option<String> = match (dedicated, mapping) {
                    (Some((eng, _)), _) => Some(eng.to_string()),
                    (None, Some(m)) if served(m) => m.engine.clone(),
                    _ => None,
                };
                let engine = engine_id.as_deref().and_then(engine_config);
                let component = match (dedicated, &engine) {
                    (Some((_, comp)), _) => Some(comp.to_string()),
                    (None, Some(_)) => Some("EngineToolRunner".to_string()),
                    _ => None,
                };
                let status = if engine.is_some() { "available".to_string() } else { rt.status.unwrap_or_else(|| "coming-soon".to_string()) };
                Tool {
                    id: rt.id,
                    name: rt.name,
                    slug: rt.slug,
                    category: rt.category,
                    description: rt.description,
                    status,
                    version: "1.0.0".to_string(),
                    execution: "client".to_string(),
                    ui: component.map(|comp| ToolUiConfig { component: Some(comp), lazy: true }),
                    engine,
                    features: features_for(mapping),
                }
            })
            .collect();

        // Catalog tools without a tools.json entry are exposed with synthesized
        // definitions so every engine-backed action is reachable.
        let mut next_id = 100_000usize;
        for m in engine_tools.tools.iter().filter(|m| m.registry_slug.is_none() && m.registry_slugs.is_empty() && served(m)) {
            let Some(engine) = m.engine.as_deref().and_then(engine_config) else { continue };
            let category = m.ui_category.clone().unwrap_or_else(|| "Developer Tools".to_string());
            *category_counts.entry(category.clone()).or_insert(0) += 1;
            let name = title_case(&m.id);
            tools.push(Tool {
                id: next_id,
                name: name.clone(),
                slug: m.id.clone(),
                category,
                description: format!(
                    "{name} – runs fully in your browser on the {} WASM engine (action `{}`).{}",
                    m.engine.clone().unwrap_or_default(),
                    m.action.clone().unwrap_or_default(),
                    m.note.as_ref().map(|n| format!(" {n}.")).unwrap_or_default()
                ),
                status: "available".to_string(),
                version: "1.0.0".to_string(),
                execution: "client".to_string(),
                ui: Some(ToolUiConfig { component: Some("EngineToolRunner".to_string()), lazy: true }),
                engine: Some(engine),
                features: features_for(Some(m)),
            });
            next_id += 1;
        }

        // Deduplicate categories and attach counts
        let mut seen_categories = std::collections::HashSet::new();
        let categories: Vec<Category> = raw_categories
            .into_iter()
            .filter(|c| seen_categories.insert(c.name.clone()))
            .map(|c| {
                let slug = c.name.to_lowercase().replace([' ', '&'], "-");
                let count = *category_counts.get(&c.name).unwrap_or(&0);
                Category {
                    name: c.name,
                    slug,
                    description: c.description,
                    count,
                }
            })
            .collect();

        Ok(Self { tools, categories })
    }

    pub fn get_tool_by_id(&self, id: usize) -> Option<&Tool> {
        self.tools.iter().find(|t| t.id == id)
    }

    pub fn get_tool_by_slug(&self, slug: &str) -> Option<&Tool> {
        self.tools.iter().find(|t| t.slug == slug)
    }

    pub fn list_tools(
        &self,
        category: Option<&str>,
        query: Option<&str>,
        status: Option<&str>,
        page: usize,
        page_size: usize,
    ) -> (Vec<Tool>, usize) {
        let q_lower = query.map(|q| q.to_lowercase());

        let filtered: Vec<&Tool> = self
            .tools
            .iter()
            .filter(|t| {
                if let Some(cat) = category {
                    if !cat.is_empty() && t.category != cat {
                        return false;
                    }
                }
                if let Some(st) = status {
                    if !st.is_empty() && t.status != st {
                        return false;
                    }
                }
                if let Some(ref q) = q_lower {
                    if !q.is_empty() {
                        let name_match = t.name.to_lowercase().contains(q);
                        let desc_match = t.description.to_lowercase().contains(q);
                        let cat_match = t.category.to_lowercase().contains(q);
                        if !name_match && !desc_match && !cat_match {
                            return false;
                        }
                    }
                }
                true
            })
            .collect();

        let total = filtered.len();
        let start = page.saturating_sub(1) * page_size;
        let paged = filtered
            .into_iter()
            .skip(start)
            .take(page_size)
            .cloned()
            .collect();

        (paged, total)
    }

    pub fn list_categories(&self) -> &[Category] {
        &self.categories
    }

    pub fn total_tools(&self) -> usize {
        self.tools.len()
    }
}

